//! Bound initializer size without adding a runtime collection or lookup.
//!
//! Each generated node has at most this many typed fields. Large areas and
//! large area registries recurse, so neither merely moves the 100-line limit
//! to a parent resolver. Small layouts retain their original generated bytes.

use std::collections::BTreeMap;
use std::fmt::Write as _;

use super::{BuildError, Contracts, Language, pascal, snake, source};

pub(super) const FIELDS_PER_RESOLVER: usize = 64;

#[derive(Debug)]
enum Value {
    Message(String),
    Area(String),
}

#[derive(Debug)]
struct Field {
    name: String,
    value: Value,
}

impl Field {
    fn key(&self) -> &str {
        match &self.value {
            Value::Message(key) | Value::Area(key) => key,
        }
    }

    fn storage(&self, nested: bool) -> String {
        match &self.value {
            Value::Message(_) => "Box<str>".to_owned(),
            Value::Area(area) => format!("{}Plain{}", qualifier(nested), pascal(area)),
        }
    }

    fn initializer(&self, nested: bool) -> String {
        match &self.value {
            Value::Message(key) => {
                format!(
                    "{}resolve(bundle, english, {key:?}, None)?.into_boxed_str()",
                    qualifier(nested)
                )
            }
            Value::Area(area) => format!(
                "{}Plain{}::resolve(bundle, english)?",
                qualifier(nested),
                pascal(area)
            ),
        }
    }
}

#[derive(Debug)]
enum Projection {
    Direct,
    Nested(Vec<usize>),
}

impl Projection {
    fn render(&self) -> Result<String, BuildError> {
        match self {
            Self::Direct => Ok(String::new()),
            Self::Nested(path) => {
                let mut output = ".inner".to_owned();
                for index in path {
                    write!(output, ".child_{index}")?;
                }
                Ok(output)
            }
        }
    }
}

#[derive(Debug)]
pub(super) struct Paths {
    areas: BTreeMap<String, Projection>,
    messages: BTreeMap<String, Projection>,
}

impl Paths {
    pub(super) fn prefix(&self, area: &str, key: &str) -> Result<String, BuildError> {
        let area_path = self
            .areas
            .get(area)
            .ok_or_else(|| source(area, "missing plain area projection"))?;
        let message_path = self
            .messages
            .get(key)
            .ok_or_else(|| source(key, "missing plain message projection"))?;
        Ok(format!(
            "{}.r#{}{}",
            area_path.render()?,
            snake(area),
            message_path.render()?
        ))
    }
}

#[derive(Debug)]
struct Layout {
    name: String,
    module: String,
    fields: Vec<Field>,
}

impl Layout {
    fn split(&self) -> bool {
        self.fields.len() > FIELDS_PER_RESOLVER
    }

    fn structure(
        &self,
        output: &mut String,
        paths: &mut BTreeMap<String, Projection>,
    ) -> Result<(), BuildError> {
        writeln!(output, "#[derive(Debug)]\nstruct {} {{", self.name)?;
        if self.split() {
            writeln!(output, "inner: {}::Root,", self.module)?;
        } else {
            for field in &self.fields {
                writeln!(output, "r#{}: {},", field.name, field.storage(false))?;
                let _previous = paths.insert(field.key().to_owned(), Projection::Direct);
            }
        }
        writeln!(output, "}}")?;
        if self.split() {
            writeln!(
                output,
                "mod {} {{\nuse super::{{Bundle, InitError}};",
                self.module
            )?;
            node(output, &self.fields, &[], paths)?;
            writeln!(output, "}}")?;
        }
        Ok(())
    }

    fn resolver(&self, output: &mut String) -> Result<(), BuildError> {
        writeln!(
            output,
            "impl {} {{\nfn resolve(bundle: &Bundle, english: &Bundle) -> Result<Self, InitError> {{\nOk(Self {{",
            self.name
        )?;
        if self.split() {
            writeln!(
                output,
                "inner: {}::Root::resolve(bundle, english)?,",
                self.module
            )?;
        } else {
            for field in &self.fields {
                writeln!(output, "r#{}: {},", field.name, field.initializer(false))?;
            }
        }
        writeln!(output, "}})\n}}\n}}")?;
        Ok(())
    }
}

pub(super) fn generate(
    output: &mut String,
    english: &Language,
    contracts: &Contracts,
) -> Result<Paths, BuildError> {
    let mut areas: BTreeMap<String, Vec<Field>> = BTreeMap::new();
    for (key, message) in &english.messages {
        let contract = contracts
            .get(key)
            .ok_or_else(|| source(key, "missing generated shape"))?;
        if contract.variables.is_empty() {
            let prefix = format!("{}-", message.area);
            let local = key
                .strip_prefix(&prefix)
                .ok_or_else(|| source(key, "missing area prefix"))?;
            areas.entry(message.area.clone()).or_default().push(Field {
                name: snake(local),
                value: Value::Message(key.clone()),
            });
        }
    }
    let root = Layout {
        name: "Plain".to_owned(),
        module: "__plain_root_cache".to_owned(),
        fields: areas
            .keys()
            .map(|area| Field {
                name: snake(area),
                value: Value::Area(area.clone()),
            })
            .collect(),
    };
    let layouts: Vec<_> = areas
        .into_iter()
        .map(|(area, fields)| Layout {
            name: format!("Plain{}", pascal(&area)),
            module: format!("__plain_area_{}", snake(&area)),
            fields,
        })
        .collect();
    let mut paths = Paths {
        areas: BTreeMap::new(),
        messages: BTreeMap::new(),
    };
    root.structure(output, &mut paths.areas)?;
    for layout in &layouts {
        layout.structure(output, &mut paths.messages)?;
    }
    root.resolver(output)?;
    for layout in &layouts {
        layout.resolver(output)?;
    }
    Ok(paths)
}

fn qualifier(nested: bool) -> &'static str {
    if nested { "super::" } else { "" }
}

fn span(length: usize) -> Result<usize, BuildError> {
    let mut span = FIELDS_PER_RESOLVER;
    while length.div_ceil(span) > FIELDS_PER_RESOLVER {
        span = span
            .checked_mul(FIELDS_PER_RESOLVER)
            .ok_or_else(|| source("plain cache", "too many fields for a cache projection"))?;
    }
    Ok(span)
}

fn node_name(path: &[usize]) -> String {
    if path.is_empty() {
        "Root".to_owned()
    } else {
        format!(
            "Node{}",
            path.iter()
                .map(usize::to_string)
                .collect::<Vec<_>>()
                .join("At")
        )
    }
}

fn node(
    output: &mut String,
    fields: &[Field],
    path: &[usize],
    paths: &mut BTreeMap<String, Projection>,
) -> Result<(), BuildError> {
    let name = node_name(path);
    let leaf = fields.len() <= FIELDS_PER_RESOLVER;
    let span = span(fields.len())?;
    let children: Vec<_> = fields
        .chunks(span)
        .enumerate()
        .map(|(index, fields)| {
            let mut child_path = path.to_vec();
            child_path.push(index);
            (child_path, fields)
        })
        .collect();
    writeln!(output, "#[derive(Debug)]\npub(super) struct {name} {{")?;
    if leaf {
        for field in fields {
            writeln!(
                output,
                "pub(super) r#{}: {},",
                field.name,
                field.storage(true)
            )?;
            let _previous = paths.insert(field.key().to_owned(), Projection::Nested(path.to_vec()));
        }
    } else {
        for (index, (child, _)) in children.iter().enumerate() {
            writeln!(output, "pub(super) child_{index}: {},", node_name(child))?;
        }
    }
    writeln!(
        output,
        "}}\nimpl {name} {{\npub(super) fn resolve(bundle: &Bundle, english: &Bundle) -> Result<Self, InitError> {{\nOk(Self {{"
    )?;
    if leaf {
        for field in fields {
            writeln!(output, "r#{}: {},", field.name, field.initializer(true))?;
        }
    } else {
        for (index, (child, _)) in children.iter().enumerate() {
            writeln!(
                output,
                "child_{index}: {}::resolve(bundle, english)?,",
                node_name(child)
            )?;
        }
    }
    writeln!(output, "}})\n}}\n}}")?;
    if !leaf {
        for (child, fields) in children {
            node(output, fields, &child, paths)?;
        }
    }
    Ok(())
}
